// Generated by CLI Printing Press (https://github.com/mvanhorn/cli-printing-press). Hand-edited to implement the novel note search (core value prop).

package cli

import (
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/spf13/cobra"

	"perfumenz-pp-cli/internal/store"
)

func newNovelSearchCmd(flags *rootFlags) *cobra.Command {
	var flagNotes string
	var flagExclude []string
	var flagMaxPrice string
	var flagLimit int
	var flagInStock bool

	cmd := &cobra.Command{
		Use:         "search",
		Short:       "Find perfumes matching specific Top/Heart/Base notes (with exclude).",
		Annotations: map[string]string{"mcp:read-only": "true"},
		Example:     "  perfumenz-pp-cli search --notes \"vanilla,oud\" --exclude \"patchouli\" --max-price 120 --json",
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 && flagNotes == "" {
				return cmd.Help()
			}
			if dryRunOK(flags) {
				fmt.Fprintln(cmd.OutOrStdout(), "would search local store for note overlap")
				return nil
			}
			dbPath := defaultDBPath("perfumenz-pp-cli")
			if dbPath == "" {
				dbPath = os.ExpandEnv("$HOME/.local/share/perfumenz-pp-cli/data.db")
			}
			db, err := store.OpenReadOnly(dbPath)
			if err != nil {
				return fmt.Errorf("opening store (run sync first): %w", err)
			}
			defer db.Close()

			// parse query notes
			qTop, qHeart, qBase := ParseNotes("Top Notes: " + flagNotes)
			// also allow free text in arg[0]
			if len(args) > 0 {
				extra := strings.Join(args, " ")
				et, eh, eb := ParseNotes("Top Notes: " + extra)
				qTop = append(qTop, et...)
				qHeart = append(qHeart, eh...)
				qBase = append(qBase, eb...)
			}
			qTop = dedup(qTop)
			qHeart = dedup(qHeart)
			qBase = dedup(qBase)

			exSet := map[string]bool{}
			for _, e := range flagExclude {
				for _, p := range strings.Split(e, ",") {
					p = strings.ToLower(strings.TrimSpace(p))
					if p != "" {
						exSet[p] = true
					}
				}
			}

			maxPrice := 0.0
			if flagMaxPrice != "" {
				maxPrice, _ = strconv.ParseFloat(flagMaxPrice, 64)
			}

			// scan perfumes (or products-json fallback)
			rows, err := db.DB().QueryContext(cmd.Context(), `
				SELECT id, data FROM resources
				WHERE resource_type IN ('perfumes', 'products', 'products-json')
				ORDER BY id
			`)
			if err != nil {
				return fmt.Errorf("query: %w", err)
			}
			defer rows.Close()

			type hit struct {
				ID    string   `json:"id"`
				Title string   `json:"title"`
				Vendor string  `json:"vendor"`
				Price string   `json:"price"`
				Notes map[string][]string `json:"notes"`
				Score int      `json:"score"`
			}
			var results []hit
			for rows.Next() {
				var id string
				var data []byte
				if err := rows.Scan(&id, &data); err != nil {
					continue
				}
				var p map[string]any
				json.Unmarshal(data, &p)

				title, _ := p["title"].(string)
				vendor, _ := p["vendor"].(string)

				// price from first variant
				price := ""
				if vs, ok := p["variants"].([]any); ok && len(vs) > 0 {
					if v0, ok := vs[0].(map[string]any); ok {
						if pr, ok := v0["price"].(string); ok {
							price = pr
						}
					}
				}
				if maxPrice > 0 && price != "" {
					if pv, err := strconv.ParseFloat(price, 64); err == nil && pv > maxPrice {
						continue
					}
				}

				// available / in-stock rough
				avail := true
				if vs, ok := p["variants"].([]any); ok && len(vs) > 0 {
					if v0, ok := vs[0].(map[string]any); ok {
						if a, ok := v0["available"].(bool); ok {
							avail = a
						}
					}
				}
				if flagInStock && !avail {
					continue
				}

				// notes from enriched or parse on fly
				var t, h, b []string
				if tn, ok := p["top_notes"].([]any); ok {
					for _, x := range tn { if s, ok := x.(string); ok { t = append(t, s) } }
				}
				if hn, ok := p["heart_notes"].([]any); ok {
					for _, x := range hn { if s, ok := x.(string); ok { h = append(h, s) } }
				}
				if bn, ok := p["base_notes"].([]any); ok {
					for _, x := range bn { if s, ok := x.(string); ok { b = append(b, s) } }
				}
				if len(t)+len(h)+len(b) == 0 {
					if bh, ok := p["body_html"].(string); ok {
						t, h, b = ParseNotes(bh)
					}
				}

				// exclude check
				skip := false
				for _, n := range append(append(t, h...), b...) {
					if exSet[n] {
						skip = true
						break
					}
				}
				if skip {
					continue
				}

				sc := NotesOverlap(qTop, qHeart, qBase, t, h, b)
				if sc == 0 && flagNotes == "" {
					// free text match on title/vendor as fallback
					lt := strings.ToLower(title + " " + vendor)
					for _, q := range append(qTop, append(qHeart, qBase...)...) {
						if strings.Contains(lt, q) {
							sc = 1
							break
						}
					}
				}
				if sc == 0 && flagNotes != "" {
					continue
				}

				results = append(results, hit{
					ID: id, Title: title, Vendor: vendor, Price: price,
					Notes: map[string][]string{"top": t, "heart": h, "base": b},
					Score: sc,
				})
			}

			// sort by score desc, then title
			// (simple)
			for i := 0; i < len(results); i++ {
				for j := i + 1; j < len(results); j++ {
					if results[j].Score > results[i].Score || (results[j].Score == results[i].Score && results[j].Title < results[i].Title) {
						results[i], results[j] = results[j], results[i]
					}
				}
			}
			if flagLimit > 0 && len(results) > flagLimit {
				results = results[:flagLimit]
			}

			if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
				enc := json.NewEncoder(cmd.OutOrStdout())
				enc.SetIndent("", "  ")
				type out struct {
					Results []hit `json:"results"`
					Query   map[string][]string `json:"query_notes"`
				}
				return enc.Encode(out{Results: results, Query: map[string][]string{"top": qTop, "heart": qHeart, "base": qBase}})
			}
			for _, r := range results {
				fmt.Fprintf(cmd.OutOrStdout(), "%s — %s — %s (score %d)\n  notes: top=%v heart=%v base=%v\n", r.Title, r.Vendor, r.Price, r.Score, r.Notes["top"], r.Notes["heart"], r.Notes["base"])
			}
			if len(results) == 0 {
				fmt.Fprintln(cmd.OutOrStdout(), "no matches (try broader notes or run sync first)")
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&flagNotes, "notes", "", "Comma-separated notes to require (matched across Top/Heart/Base)")
	cmd.Flags().StringSliceVar(&flagExclude, "exclude", nil, "Notes to exclude (any pyramid)")
	cmd.Flags().StringVar(&flagMaxPrice, "max-price", "", "Maximum price (from first variant)")
	cmd.Flags().IntVar(&flagLimit, "limit", 20, "Max results")
	cmd.Flags().BoolVar(&flagInStock, "in-stock", false, "Only items with available variants")
	return cmd
}
